// Generated by vibelang from src/config/new-session-location.ts; the migrate flow writes it again with each batch.
export function newSessionLocation(mode, launchDirectory, current, unavailable) {
    if (mode === "inherit" &&
        current &&
        (current.directory !== unavailable?.directory || current.workspaceID !== unavailable.workspaceID))
        return current;
    return { directory: launchDirectory };
}
